import { mkdir, readFile, writeFile } from 'node:fs/promises'
import { join, resolve } from 'node:path'
import { env } from '../env.ts'

/** Where picture bytes live. The DB row (generated_asset) is the source of truth for who owns what; storage is just blobs. */
export interface AssetStorage {
  put(key: string, bytes: Uint8Array, mime: string): Promise<void>
  get(key: string): Promise<Uint8Array | null>
}

/** Keys are generated by us (nanoid + extension) — still validated, so a bad row can never escape the storage root. */
const SAFE_KEY = /^[A-Za-z0-9_-]{16,64}\.(png|jpg|webp)$/
export const assertSafeKey = (key: string) => {
  if (!SAFE_KEY.test(key)) throw new Error('invalid storage key')
  return key
}
export const extensionFor = (mime: string) => (mime === 'image/jpeg' ? 'jpg' : mime === 'image/webp' ? 'webp' : 'png')

/** Dev: files under ASSET_DIR (gitignored). Not for production — container disks are ephemeral. */
export class LocalDiskStorage implements AssetStorage {
  private readonly root: string
  constructor(dir: string) {
    this.root = resolve(dir)
  }
  async put(key: string, bytes: Uint8Array): Promise<void> {
    await mkdir(this.root, { recursive: true })
    await writeFile(join(this.root, assertSafeKey(key)), bytes)
  }
  async get(key: string): Promise<Uint8Array | null> {
    try {
      return new Uint8Array(await readFile(join(this.root, assertSafeKey(key))))
    } catch (e) {
      if ((e as NodeJS.ErrnoException).code === 'ENOENT') return null
      throw e
    }
  }
}

/** Minimal surface of the S3 client we use (lets tests inject a fake without AWS). */
export interface S3Like {
  send(command: unknown): Promise<{ Body?: { transformToByteArray(): Promise<Uint8Array> } }>
}

/**
 * Production: a PRIVATE bucket (no public access) — pictures are served through our API's capability URL, which keeps
 * access control, caching headers and the kill switch in one place. IAM role needs s3:PutObject + s3:GetObject on `prefix/*`.
 */
export class S3Storage implements AssetStorage {
  constructor(
    private readonly bucket: string,
    private readonly client: S3Like,
    private readonly commands: { Put: new (input: never) => unknown; Get: new (input: never) => unknown },
    private readonly prefix = 'generated/',
  ) {}
  async put(key: string, bytes: Uint8Array, mime: string): Promise<void> {
    await this.client.send(new this.commands.Put({ Bucket: this.bucket, Key: this.prefix + assertSafeKey(key), Body: bytes, ContentType: mime, CacheControl: 'public, max-age=31536000, immutable' } as never))
  }
  async get(key: string): Promise<Uint8Array | null> {
    try {
      const out = await this.client.send(new this.commands.Get({ Bucket: this.bucket, Key: this.prefix + assertSafeKey(key) } as never))
      return out.Body ? await out.Body.transformToByteArray() : null
    } catch (e) {
      const name = (e as { name?: string }).name
      if (name === 'NoSuchKey' || name === 'NotFound') return null
      throw e
    }
  }
}

let cached: AssetStorage | undefined
export async function getStorage(): Promise<AssetStorage> {
  if (cached) return cached
  if (env.ASSET_STORAGE === 's3') {
    const { S3Client, PutObjectCommand, GetObjectCommand } = await import('@aws-sdk/client-s3') // only loaded in production
    cached = new S3Storage(env.ASSET_BUCKET!, new S3Client({ region: env.ASSET_REGION! }) as unknown as S3Like, { Put: PutObjectCommand, Get: GetObjectCommand })
  } else cached = new LocalDiskStorage(env.ASSET_DIR)
  return cached
}
/** tests */
export const setStorage = (s: AssetStorage | undefined) => void (cached = s)
